INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Аҳамияти беҳтар кардани намоиш дар парҳези донуи эспрессо</h2>\n<p>Парҳези донуҳои равғанӣ ва донуӣ, аз ҷумла <strong>эспрессо</strong> (ки аксаран нахустин ё сабз онро бо ин ном дар бозорҳои маҳаллӣ шинос мебошанд ё баъзан дар баъзе тизимҳои намоиши нав таъмини намоиш/намоиши хонагӣ истифода мешавад), ба идоракунии дақиқи реша ва намӣи хок ниёз дорад. Яке аз муҳимтарин параметрҳои техникӣ дар тизимҳои намоиши нуқтӣ ва намоиши нӯрӣ муайян кардани дурусти <strong>масофаи нӯри эспрессо</strong> аз ҳамкор ва масофа байни нӯрҳои ҳамсоя аст. Ҷойгиршавии нодуруст на танҳо ба талафоти об оварда мерасонад, балки метавонад боиси парши донуҳо ё камшавии пӯшиши набототи мақсаднок гардад. Дар ин дастур мо меъёрҳои тавсияшударо бар асоси чуқурии реша, намуди дону ва шароити иқлимӣ тафсир мекунем. Бо назардошти ҳассосияти ин наботот ба камбуди об дар марҳилаҳои ибтидоии афзоиш, интихоби дурусти ин масофа метавонад то 30% дар самаранокии охирин таъсир расонад. Инчунин, фаҳмиши чуқур аз физиологияи реша ва роҳи пуршавии об дар хокҳои гуногун, асоси тарҳрезии ҳар тизими намоиши муваффақ аст. Бисёре аз кишоварзони, ба далели нашносогӣ бо ин асосҳо, аз тизимҳои намоиши нӯрӣ истифодаи комил намекунанд, ки ба талафоти манбаъҳои об ва пастшавии сифати маҳсулот оварда мерасонад. Бинобар ин, санҷиши дақиқи тағйирёбандаҳои муҳитӣ ва набототӣ қадами аввал барои расидан ба як тизими намоиш доимӣ аст.</p>\n\n\n<h2>Параметрҳои техникӣ муайянкунандаи масофаи намоиши нӯрӣ</h2>\n<h3>Таъсири чуқурии решаи донуи эспрессо</h3>\n<p>Спаржа (аспарагус) як наботи яксола бо системаи решаи рақамӣ (Taproot), чунони реша метавонад вобаста ба навис ва шароити хок аз 40 то 80 сантиметр тағйир ёбад. Системаи навъи таҳп бояд тавре тарҳрезӣ шавад, ки минтақаи тар (Wetted Zone) дақиқан бо ҳудуди фаъолияти решаҳои асосӣ мувофиқат кунад. Агар масофаи навъи таҳп аз маркази сутун хеле зиёд бошад, решаҳо баҳри ҷустуҷӯи об ба энергияи бештар таваҷҷӯҳ доранд, ки ба стресси физиологӣ оварда мерасонад. Баъд, масофаи хеле наздик баръакс, боиси хароҷоти оби дар минтақаҳои бе набот мешавад. Ҳоло аз чунони реша, суръати афзоиши реша низ нақши муҳим мебозад. Дар хокҳои бо ҳавошумии бад, решаҳо сатҳӣтар меафзоянд ва масофаи навъ бояд камтар бошад, то намӣ аз даст наraft. Аз тарафи дигар, дар хокҳои рудоғӣ бо сатҳи баланди шуннӣ, решаҳо барои ёфтани об ба чунони бештар мераванд ва масофаи навъ метавонад каме зиёд шавад, шароити он ки чунони насби навъ мувофиқ бошад. Ин мувозинати наздик ба назорати доимии ҳолати хок ва набот ниёз дорад. Тағйирёбии фаслии дар ҳарорат ва намии ҳаво низ ба суръати буғшавӣ ва зарурати об барои набот таъсир мерасонад ва бояд дар ҳисобҳои ниҳоии масофагузорӣ ба назар гирифта шавад. Бинобар ин, як масофаи мутавассит барои соли тамоми шояд беҳтарин набошад ва ба танзимоти динамикӣ ниёз дорад.</p>\n<h3>Фарқиятҳои навис ва нақшаи катшавӣ</h3>\n<p>Ду усули асосӣ барои парҳоз кардани қаҳва дар системаи қатрафавкӣ вуҷуд дорад: усули қаторӣ (Row) ва усули паҳншавӣ (Broadcast). Дар усули қаторӣ, ки барои нозукҳои донадӯзӣ маъмул аст, наворҳои рӯйхӯри (tip) ба таври параллел бо қаторҳои ғаношӣ ҷойгир мешаванд. Масофаи стандартии тавсияшуда одатан дар вобастагӣ аз 20 то 30 сантиметр аз хати дунӣ ҷойгир мешавад. Дар усули паҳншавӣ, ки бештар барои истеҳсоли биёҳ ё сабзакҳои қаҳва истифода мешавад, ҷобаҷокунии наворҳо бо намуди лонаӣ (Hilb) ё қатории баъд-баъд бо масофаҳои 50 то 60 сантиметрӣ амалӣ карда мешавад. Интихоби нақши ғаношӣ бояд мақсади маҳсули ниҳоиро мувофиқ кунад. Барои истеҳсоли донаҳои сифатнок, усули қаторӣ бо масофаи камтари навор тавсия мешавад, то ғизокишӣи решаҳо бетартифтар шавад. Барои истеҳсоли колоси ё гиёҳҳои ҷуфт-ҷуфт, метавон аз масофаҳои бештар истифода бурд, то хароҷоти насб кам шавад. Инчунин, зичии ғаношӣ худ ба масофаи навор таъсир мерасонад. Зичии баландтар ниятро ба тақсимоти дақиқтари об ва масофаи камтари навор аз ҳар гиёҳ талаб мекунад. Ин нуқтаҳои нозук дар тарроҳии ибтидоии система хеле муҳиманд ва эътироф накардани онҳо метавонад ба рақобати сахт байни гиёҳҳо барои манбаъҳои об оварда расонад.</p>\n\n<h2>Стандартҳои тавсияшудаи масофагузории наворҳои рӯйхӯри (tip)</h2>\n<p>Барои ноил шудан ба ҳосили мувофиқ, бояд аз дастуриҳоҳои зерин риоя кард. Ин рақамҳо бар асоси таҳқиқоти илмӣ-техникӣ оид ба обёри дақиқ дар минтаҳое, ки хукуни гилӣ ва шаблонӣ доранд, танзим карда шудаанд: инчунин, андозаҳои лӯлаи асосӣ ва фишори систем ба ҳаҷми баромад ва, бинобар ин, ба радиуси баҳоридашудаи нӯҳ таъсир мерасонад. Баъд аз муайян кардани масофаи ибтидоӣ, зарур аст, ки бо таҷрибаҳои майдонӣ радиуси воқеии баҳоридашударо муайян намуда, дар сурати лозим масофаро ислоҳ кунад. Диққат ба сифати тобукҳо ва фоизи таракониш онҳо низ метавонад дар муайян кардани зичии наботот ва қабати решаҳо таъсиранд. Барои навъҳое, ки решаҳои хуб доранд, масофаи каме зиёдтар метавонад қабул шавад. Аммо барои навъҳои заиф, бояд ҳангоми муайян кардани масофа бандаро ҳассосӣ зоҳир кард, то хатари хушк шудани решаҳо кам шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-اسپرس-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت اسپرس: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>drip tape spacing row layout crop اسپرس</figcaption></figure>\n\n<ul>\n<li><strong>Масофаи нӯҳ аз хати ғайри: </strong> Дар кӯшӯти сафҳои испресс, масофаи 25 сантиметрӣ ҳамчун нуқтаи беҳтарин шинохта мешавад. Ин масофа мувозинати хубро байни парҳизури обёри ва пӯшишгирӣи решаҳо таъмин мекунад.</li>\n<li><strong>Ғолнокии нӯҳи тиб: </strong> Барои испресс, лӯлаҳои пластикӣ ё нӯҳҳои полиэтилен бо диаметр 16 ё 20 миллиметр мувофиқ аст. Диаметри хурдтар, агар сӯробҳо маҳкам шаванд, метавонад ба тағйирёбии фишор оварда мерасонад.</li>\n<li><strong>Биниҳои байни сафҳои асосӣ: </strong> Масофаи байни сафҳои асосии ниҳолнавоии испресс одатан 30 то 35 сантиметр мебошад. Нӯҳи тиб набояд байни сафҳо ҷойгир бошад, балки бевосита дар канори сафи ниҳолнавоӣ насб мешавад, то обро ба минтақаи рақобати решаҳо расонад.</li>\n<li><strong>Ҷоеи насбибнии лентӣ:</strong> Ҷоеи 10 то 15 сантиметр зери сатҳи хок беҳтарин интихоб аст. Ҷоеи бештар метавонад боиси кам шудани суръати паҳн шудани об ба рӯи решаҳои хурд гардад ва ҷоеи камтар ба бухоршавӣ майл дорад.</li>\n</ul>\n\n\n<h2>Нуктаҳои амалӣ барои насб ва нигоҳубини системаи лентавии ирригатсионӣ</h2>\n<h3>Тарзи дурусти насб дар хок</h3>\n<p>Яке аз хатогиҳои маъмул ҷойгир кардани лентӣ дар сатҳи хок аст. Барои пешгирӣ аз бухоршавӣ ва коррозияи UV, бояд лентиро то ҷоеи 10 то 15 сантиметрии хок бирасонед. Инчунин, кунҷи пайвасткунии лентӣ ба лӯлаи асосӣ бояд 45 дараҷа бошад, то ба ҷараёни об муқоимат паҳлу надарад. Истиҳоди ҳалшудаи маводҳои кимиёвӣ тавассути лентии ирригатсионӣ метавонад дар марҳилаи афзоиш аз бемориҳои реша пешгирӣ кунад; бинобар ин, нигоҳ доштани тозагии каналҳо аз решаҳои кальсий муҳим аст. Истифодаи филтрҳои мувофиқ дар оғози система ва шустани лентавиро ба таври даврӣ умри фоиданоки системаро меафзояд. Инчунин, таъмини баробарии баландии сатҳҳои шӯр ба он сабаб мешавад, ки фишори гидравликӣ дар тамоми дарозии лентӣ якхела боқӣ мемонад. Дар деҳоти дағал, лозим аст, ки диафрагмаҳои мувозинатдиҳандаи фишоро насб кард, то барои пешгирӣ аз ирригатсияи зиёд дар нуқтаҳои поёнӣ.</p>\n<h3>Мудиряти фишор ва дебит</h3>\n<p>Система бояд чунин тарҳрезӣ шавад, ки суръати ғарқшавии об (Soil Infiltration Rate) бо дебитҳои бармақамаи тампонҳо мувофиқат кунад. Агар хокҳои вазнини гилӣ доред, давоми ирригатсия бояд кӯтоҳтар бошад, аммо такрораш бештар. Дар хокҳои қумӣ, дебити баландтар лозим аст. Барои ҳисобкунии дақиқ, метавонед ба <a href="https://navar-abyari.ir/%D8%A7%D9%86%D9%88%D8%A7%D8%B9-%D8%B3%DB%8C%D8%B3%D8%AA%D9%85-%D9%87%D8%A7%DB%8C-%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C/">Намудҳои системаҳои ирригатсионӣ</a> Омозеҳ кунед, то вобораи худро вобора кунед. Танзими дурусти фишори дохили система калиди асосии пешгирии тахшиши лавҳаҳо ва таъмини парокандагии баробар об аст. Назорати давомдоиши фишор бо истифода аз манометрҳои рақамӣ кӯмак мекунад, то инҳирофҳоро зуд пайдо ва ислоҳ кардан. Ҳамчунин, фаслияти ниёзи обии эспрессо-шашоро дидагирӣ кунед ва барномаи обориро асос карда ба маълумотҳои илми абҳурош ва намнокунӣ танзим кунед.</p>\n\n<h2>Таъсири ҷойгиршавӣ бар самаранокии ниҳоӣ</h2>\n<p>Тағйироти хурд дар масофаи лавҳаи дрип меъёри метавонад бар <a href="https://navar-abyari.ir/vegetable-yield-per-hectare-guide/">самаранокии набототҳо дар ҳар гектар</a> таъсир расонад. Дар ҳолати эспрессо, ҳадафи ниҳоӣ зиёди ҳосил аст. Маълумотҳо нишон медиҳанд, ки нақшҳои оборири якхела бо масофаи лавҳа 25 сантиметрӣ дар муқоиса бо масофаи 40 сантиметрӣ, тақрибан 15 фоиз самаранокии баландтарро дар истеҳсои сабз ва ҳосил нишон доданд. Ин ба сабаби тӯфӣ беҳтари қисм намнокунӣ бо системаи реша дар масофаи кам аст. Инчунин, идоракунии муносиби ин система метавонад дар давоми муддати дароз ба <a href="https://navar-abyari.ir/musir-yield-per-hectare-increase-production-methods/">зиёди истеҳсои маҳсулот дар гектар</a> кӯмак расонад, ҳатто агар эспрессо-шасро ҳамчун қисми хурд дар ҳалқаи ҷойкунии намудҳо дида шавад. Офтимализатсияи масофаи лавҳаи дрип мушоихат самаранокии иқтисодии заминро таъсир мерасонад. Кам кардани заҳматҳо ва зиёд кардани баробарии афзоиши наботот, ба паст шудани маблағҳои иловагӣ, ба монанди бокӣ ва мубориза бо зарарорҳо оварда мерасонад. Системаи оборири самаранок на танҳо истеҳсоро баланд мебардорад, балки сифати донатонро ҳам беҳтар мекунад, ки барои нархгузории беҳтар дар бозор хеле муҳим аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-اسپرس-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت اسپرس: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>drip tape spacing row layout crop эспрессо-шасор</figcaption></figure>\n\n\n\n<h2>Саволҳои маъмулӣ (FAQ)</h2>\n<h3>Оё нӯрипӣ (тип) метавонад дар заҳҳои сангроғон барои паҳлӯи (аспрес) истифода шавад?</h3>\n<p>Бале, аммо дар заҳҳои сангроғон сунбкунандагӣ баланд аст. Беҳтар аст аз нӯрҳои ғафстарӣ ва бо фосилаи камтар аз хати бодир (тақрибан 20 сантиметр) истифода бурда, шумораи обёрорӣро зиёд намуд, то аз хориҷшудагии амиқи об пешгирӣ шавад. Дар ин шартҳо, даромади нӯр бояд танзим карда шавад, то об ба зудӣ ба чуқурӣ нарвад ва дар минтакаи реша монанд. Инчунин, истифодаи пӯшишҳои растакунӣ (Mulch) дар сатҳи заҳ, ба нигоҳ доштани намӣ кӯмак мерасонад ва таъсирҳои манфии заҳи сангроғонро кам мекунад.</p>\n<h3>Фосилаи нӯрипӣ (тип) дар парҳези омехта чӣ қадар аст?</h3>\n<p>Агар паҳлӯи (аспрес) бо дигар маҳсулот чун чубуканон ё дигар растаҳои решагӣ парҳез шавад, фосилаи нӯр бояд чунин танзим карда шавад, ки минтақаи намииданид (намӣшуда) ду раста ҳампаҳлӯй надоранд. Дар ин ҳолат, истифодаи роҳнамоии <a href="https://navar-abyari.ir/miqdori-hasili-chaudor-dar-yek-hektar/">Маблағи маҳсули ғадобард (хауардар) дар як гектар</a> метавонад кӯмакрасон бошад, то фазои парҳезшавандоҳӣ беохтар карда шавад. Инчунин, зарурати гуногуни об барои ду раста бояд ба назар гирифта шавад ва баъзан тарҳрезии ду нӯри алоҳида барои ҳар раста беҳтар аз ғайридур кардани як нӯр бо ду растаи гуногун аст. Парҳези омехта ба нигоҳубини дугона дар марҳалаи тарҳрезии системаи обёрӣ ниёз дорад.</p>\n<h3>Оё фосилаи нӯрипӣ (тип) бо бодираи ҷаву обӣ якхела аст?</h3>\n<p>Не, ба вуҷуди он ки ҳарду навъи дӯғдор мебошанд, амики насб кардан ва ниёз ба оби сӯбӣ ба таври фарқоварӣ мебошад. Шумо метавонед муқоисаро бо <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%ac%d9%88-%d8%a2%d8%a8%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/"> миқдори дӯғ сӯбӣ дар гектар</a>  анҷом диҳед, то фарқияти зичии дӯғдорӣ ва ниёз ба оби ин ду наъботро беҳтар фаҳмед. Спелта одатан фосилаи бастари камтарро талаб мекунад. Сӯбӣ бо сабаби андозишани бардори бузургтар ва зичии насби гуногун, ба фосилавзнии васеътар ва дараёни баландтар ниёз дорад. Дарк накардани ин ду навъ метавонад боиси оби нокӯфии спелта ё ҳарошиш аз ҳад зиёди сӯбӣ гардад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-اسپرس-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت اسپرس: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>дурпост дар барори насби дӯғ спелта</figcaption></figure>\n\n<h3> Беҳтарин ғафсии дурпост кадом аст?</h3>\n<p> Барои навъи дӯғдори спелта, дурпост 16 то 20 миллиметр мувофиқ аст. Дурпости назоктар ба мутлақоти (Clogging) дастрас мебошанд ва дурпости ғафстрар ҳадафи беҳтарро барои система надоранд, магар ин ки барои навъи чӯбӣ ё дӯг хеле калон бошад. Интихоби ғафсии мувофиқ тавозуни байни хароҷоти ибтидоии насб ва самаранокии дилхоҳ аст. Дурпости сифатноктар аз полиетилен, бо муқовимати баланди UV, дар шартҳои душвори ҳаёти деҳот тӯли умр баландтар доранд ва ба ивазкунии даври камтар ниёз доранд.</p>\n\n<h2>Хулоса</h2>\n<p> Интихоби дуруст <strong>Фосилаи банди туби экспресс</strong> Калیدи муваффақият дар оварии ин наботат инҳисоб мешавад. Риъояи фосилаи 25 сантиметрӣ аз хати бодорон дар хӯки реғу ва 20 сантиметрӣ дар хӯки куморӣ, илова бар гузоштани чуқураш ва истифодаи лӯлаҳои сифатнок, метавонад хароҷоти овариро коҳиш диҳад ва сифати донаро зиёд кунад. Ҳамеша пеш аз оғози фавсали кишт, таҳлили гузариши хӯкро анҷом диҳед ва бар асоси он модели бандидории худро танзим кунед. Дӯдони амилҳои гуногун, аз ҷумла <a href="https://navar-abyari.ir/harvest-yield-black-radish-hectare-factors/">Амилҳои таъсирбахш ба ҳосили ҳектар</a> Дар дигар маҳсулоти имитатсияшуда метавонад ба шумо бештар дарки диҳад, зеро принсипҳои физикии интиқоли об якхела аст. Бо риояи ин стандартҳо, системаи оварии худро ба ягон субструктураи ҳомоякнак ва зич табдил медиҳед. Инчунин, санади таҷрибаҳои мазӯа ва сабти маълумоти оварӣ бар солҳои оянда, метавонад ба беҳтаракунии доимии раванд ва зиёд шудани самаранокӣ кӯмак кунад.</p>','Фаволаи нӯҳи тип дар кӯрди қӯнҷиш: меъёрҳои тавсияшуда ва принсипҳои расидан','Дар ин мақолаи ихтисосӣ, мо меомӯзед оид ба меъёрҳои дақиқи масофаи қатори системаи қутта-барои боғҳои эспрессо. Аз интихоби қаллокии мувофиқи ҷӯра то ҷойгиркунии қаторҳо ва нуқтаҳои муҳими зиёд кардани самаранокии обдиҳӣ.','publish','closed','closed','favola-ichip-qucnis-kurdon-standard-havolar',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
